Translate("zhCN", "trade-district", {
	title = "贸易区",
	sections = {
		{
			title = "概述",
			text = [=[贸易区是{link:stormwind-city}暴风城{/link}最繁忙的城区。它的街道上有银行、拍卖行、名为{link:ginro-hearthkindle}金{/link}玫瑰的旅店，以及各行各业的店铺。{link:morgan-pestle}摩根·匹斯特{/link}在这里出售他的药水，{link:elling-trias}提亚斯{/link}一家在这里卖奶酪。狮鹫在城区边缘降落，载来王国各地的信件和旅人。在所有讨价还价之下，流淌着这座城市最古老的买卖：流言。中午在贸易区听到的事，傍晚就会传到要塞里。]=],
		},
	},
})

Translate("zhCN", "cathedral-square", {
	title = "教堂广场",
	sections = {
		{
			title = "概述",
			text = [=[教堂广场是{link:stormwind-city}暴风城{/link}中心的一片开阔大广场。广场北端耸立着{link:cathedral-of-light}圣光大教堂{/link}，那是南方最大的{link:holy-light}圣光{/link}殿堂。广场四周有市政厅——建筑师{link:baros-alexston}巴隆斯·阿历克斯顿{/link}在那里办公——以及城中神职人员和圣骑士受训的殿堂。士兵们在石板地上操练。朝圣者前来祈祷。在这座广场上，暴风城展现出它希望被人看到的样子：虔诚、有序而强大。]=],
		},
	},
})

Translate("zhCN", "old-town", {
	title = "旧城区",
	sections = {
		{
			title = "概述",
			text = [=[旧城区位于{link:stormwind-city}暴风城{/link}东部，那里街道狭窄，建筑比别处更古老。城中的兵营和一家为士兵供应盔甲的店铺都在这里。这里也是{link:si-7}军情七处{/link}的所在地。{link:master-mathias-shaw}马迪亚斯·肖尔大师{/link}在兵营中办公，他的特工从大多数市民从未留意过的门户进进出出。在小巷里，人们各管各的事，很少多问。新到都城的士兵会先来到这里，领取武器、安排住处，再被派往王国需要他们的地方。]=],
		},
	},
})

Translate("zhCN", "dwarven-district", {
	title = "矮人区",
	sections = {
		{
			title = "概述",
			text = [=[矮人区位于{link:stormwind-city}暴风城{/link}北部，靠近城墙。住在暴风城的{link:ironforge}铁炉堡{/link}{link:dwarves}矮人{/link}把这个城区当作自己的地盘。这里有城中最喧闹的{link:the-cauldron}熔炉{/link}、一座{link:explorers-league}探险者协会{/link}的大厅，以及{red:deeprun-tram}矿道地铁{/red}的入口，地铁从山脉之下通往铁炉堡。这个城区是两个王国古老友谊的象征。这里的铁匠们毫不低调地说，暴风城最好的钢铁就出自他们这条街。]=],
		},
	},
})

Translate("zhCN", "mage-quarter", {
	title = "法师区",
	sections = {
		{
			title = "概述",
			text = [=[法师区位于{link:stormwind-city}暴风城{/link}西南部，紫色的屋顶在运河之上拔起。巫师圣殿矗立在它的中心，城中的法师在那里教授学徒{link:arcane-magic}奥术{/link}。这里的魔法并非全都合法。在一家名叫“被宰的羔羊”的酒馆下面，术士们在地窖中聚会，研习教会所谴责的力量。在城区附近的运河边，矗立着{link:the-stockade}监狱{/link}阴森的大门，那里的看守已被他们自己的囚犯逼退到了门口。]=],
		},
	},
})

Translate("zhCN", "the-park", {
	title = "公园",
	sections = {
		{
			title = "概述",
			text = [=[公园是{link:stormwind-city}暴风城{/link}西北部一片绿意盎然的城区。古树伫立在幽静的小径之间。它是这座拥挤城市中最宁静的地方，紧挨着{link:stormwind-keep}暴风要塞{/link}的城墙之下。市民们来这里休息、散步和交谈。罗伊·勒维尔斯在附近办了一个读书会。会员们在打烊后聚在一个地窖里，用从{link:royal-library}皇家图书馆{/link}借来的书争论历史与思想，还有罗伊乐于与帮助他的人分享的茶点。]=],
