	},
})

Translate("zhCN", "stormwind-keep", {
	title = "暴风要塞",
	aliases = { "暴风城堡" },
	sections = {
		{
			title = "概述",
			text = [=[暴风要塞矗立在城市北端，是乌瑞恩家族历代国王的居所。它的王座大厅日夜有人把守。年幼的{link:anduin-wrynn}安度因国王{/link}坐在{link:bolvar-fordragon}伯瓦尔·弗塔根公爵{/link}身旁，{link:katrana-prestor}卡特拉娜·普瑞斯托女士{/link}在一旁侍奉着他们二人。要塞中还有{link:royal-library}皇家图书馆{/link}、城市卫兵的办公处，以及一座宫廷领主们散步的围墙花园。并不是那座花园里的每一场谈话都适合忠诚之人听到。]=],
		},
	},
})

Translate("zhCN", "stormwind-harbor", {
	title = "暴风城港口",
	aliases = { "暴风城的港口" },
	sections = {
		{
			title = "概述",
			text = [=[暴风城的港口再次繁忙起来。一艘新船如今从它的南码头出发，渡海前往{link:darkshore}黑海岸{/link}岸边的{link:auberdine}奥伯丁{/link}，在王国与{link:night-elves}暗夜精灵{/link}的土地之间运送补给、信件和旅人。文书们按箱清点货物，码头工人永远不够用。卫兵和炮手监视着水面。城里的商人已经派亲属渡海到奥伯丁做生意，而求援的信件则从另一头寄回来。多年来第一次，这座城市越过大海向外眺望。]=],
		},
	},
})

Translate("zhCN", "valley-of-heroes", {
	title = "英雄谷",
	sections = {
		{
			title = "概述",
			text = [=[英雄谷是通往{link:stormwind-city}暴风城{/link}的宏伟大道。来自{link:elwynn-forest}艾尔文森林{/link}的道路越过一座长桥，从高大的雕像之间穿过，然后抵达城市的正门。每一位从陆路来到暴风城的旅人都要从它们脚下走过。城市卫兵在这里严密把守，因为城门是都城的第一道防线，也是访客看到的第一样东西。王国远方元帅们的信使在这里抵达，侍从们把他们的消息从城门送到王座大厅。]=],
		},
	},
})

Translate("zhCN", "cathedral-of-light", {
	title = "圣光大教堂",
	aliases = { "圣光教堂" },
	sections = {
		{
			title = "概述",
			text = [=[圣光大教堂是{link:kingdom-of-stormwind}暴风王国{/link}最伟大的{link:holy-light}圣光{/link}殿堂。它耸立在城市中心的{link:cathedral-square}教堂广场{/link}之上。{link:archbishop-benedictus}大主教本尼迪塔斯{/link}在它的殿堂中领导着教会。牧师们在那里教导信徒，{link:grayson-shadowbreaker}格雷森·沙东布瑞克公爵{/link}则在它的侧厅中训练王国的圣骑士。]=],
		},
		{
			title = "圣物的守护者",
			text = [=[大教堂所做的不只是祈祷。神圣之物被送到这里妥善保管，被诅咒之物被送到这里加以净化。当被诅咒的帕{link:farmer-ray}雷{/link}斯之眼被找回时，它被送到了大主教手中。当一尊{link:terenas-menethil}泰瑞纳斯·米奈希尔{/link}国王的小雕像在{link:wetlands}湿地{/link}被发现时，{link:holy-light}圣光{/link}似乎在它周围汇聚，它也被送到大教堂妥善保管。{link:stormwind-city}暴风城{/link}的信徒相信，进入大教堂的东西会得到很好的守护。]=],
		},
		{
			title = "大教堂的侍奉者",
			text = [=[住在大教堂里的不只是大主教。主教、修士和侍僧在它的殿堂中侍奉。克里斯托弗修士在那里用{link:royal-library}皇家图书馆{/link}的书准备他的布道，{link:captain-grayson}格雷森{/link}{link:duke-nicholas-zverenhoff}公爵{/link}的圣骑士在它的墙内受训。教会的声音从这里传到{link:northshire-abbey}北郡修道院{/link}，传到王国的每一座礼拜堂。]=],
		},
	},
})

Translate("zhCN", "royal-library", {
	title = "皇家图书馆",
	aliases = { "暴风城图书馆", "暴风城的图书馆" },
	sections = {
		{
			title = "概述",
			text = [=[皇家图书馆位于{link:stormwind-keep}暴风要塞{/link}之内。它保存着王国的书面记忆：史书、论著和宫廷的记录。它的管理者{link:milton-sheaf}米尔顿·西弗{/link}会去寻找传闻中任何地方的遗失书籍，从{link:duskwood}暮色森林{/link}到已陷落的{link:alterac-mountains}奥特兰克{/link}那些失落的图书馆。]=],
		},
		{
			title = "借书",
			text = [=[图书馆的书架并不只为领主们保留。它把书借给学者和神职人员，如今也和城中一个小小的读书会交换书籍。那个读书会所要的书名，道出了平民百姓如今在思考什么：{link:horde}部落{/link}袭击的记述、托尔{link:baine-bloodhoof}贝恩{/link}诸王的征服，还有一些更奇怪的书名。]=],
		},
		{
			title = "图书管理员",
			text = [=[{link:milton-sheaf}米尔顿·西弗{/link}掌管着图书馆，丹亚·托瓦尔德照看着它的书架和借阅。他们都是一丝不苟的人。离开图书馆的书应当以同样的状态归还；爱惜书籍的借阅者，无论书中言辞多么令人不安，都欢迎他再来借阅。]=],
		},
	},
})

